"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1133],{19181:e=>{e.exports=JSON.parse('{"functions":[{"name":"getPriceLevel","desc":"Returns the player\'s price level, or `nil` if it could not be determined.\\n\\nYields on the first call per player while `GetUsersPriceLevelsAsync` is queried;\\nlater calls are served from the cache. The lookup is wrapped in a `pcall`, so a\\nthrottled or failing request returns `nil` rather than erroring \u2014 callers must\\nhandle `nil` by falling back to unadjusted pricing.","params":[{"name":"player","desc":"Player to look up","lua_type":"Player"}],"returns":[{"desc":"Price level, or nil when unavailable","lua_type":"number?"}],"function_type":"static","realm":["Server"],"source":{"line":36,"path":"src/Shared/Modules/getPriceLevel.luau"}}],"properties":[],"types":[],"name":"getPriceLevel","desc":"Looks up a player\'s Roblox regional price level, the input to\\n[adjustValueByUserPriceLevel].\\n\\nResults are cached per user for the lifetime of their session; the cache entry is\\ndropped on [Players.PlayerRemoving] so a rejoining player is re-queried.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","source":{"line":13,"path":"src/Shared/Modules/getPriceLevel.luau"}}')}}]);